equal_reserve_index_chain.chain_added_source:
struct ChainEntry<K, V> {
  key: K;
  value: V;
  next: u64;
}

struct ChainMap<K, V> {
  heads: Box<Slots<u64>>;
  entries: Box<Slots<ChainEntry<K, V>>>;
}

fn chain_heads_new(capacity: u64) -> result: Box<Slots<u64>> pure contract {
  requires capacity <= 8192_u64;
  ensures result.inner.len == capacity;
} {
  let heads = box_slots_new::<u64>(capacity: capacity);
  for @heads (
    index in 0_u64..capacity,
    invariant minimum: heads.inner.len >= index,
    invariant maximum: heads.inner.len <= index,
    invariant capacity: heads.inner.cap >= capacity
  ) {
    place_back(window: &heads.inner, value: 18446744073709551615_u64);
  }
  invariant complete_min: heads.inner.len >= capacity;
  invariant complete_max: heads.inner.len <= capacity;
  return move heads;
}

fn chain_insert<interface HashMapKey<K, E>, V>(map: &ChainMap<K, V>, key: K, value: V, env: &E) -> result: Result<unit, HashMapPair<K, V>> reads(env), writes(map) {
  let hash = HashMapKey::hash(env: env, key: &key);
  let capacity = map^.heads.inner.len;
  if capacity == 0_u64 {
    let offered = HashMapPair<K, V>(key: move key, value: move value);
    return Err<unit, HashMapPair<K, V>>(error: move offered);
  }
  if map^.entries.inner.len == map^.entries.inner.cap {
    let offered = HashMapPair<K, V>(key: move key, value: move value);
    return Err<unit, HashMapPair<K, V>>(error: move offered);
  }
  let bucket = hash % capacity;
  let previous = map^.heads.inner[bucket];
  let index = map^.entries.inner.len;
  let node = ChainEntry<K, V>(key: move key, value: move value, next: previous);
  place_back(window: &map^.entries.inner, value: move node);
  set map^.heads.inner[bucket] = index;
  return Ok<unit, HashMapPair<K, V>>(value: unit);
}

fn chain_lookup<interface HashMapKey<K, E>, V, F, R, fn observe(env: &F, key: &K, value: &V) -> result: R reads(key), reads(value), writes(env)>(map: &ChainMap<K, V>, key: &K, key_env: &E, visit_env: &F) -> result: Result<R, unit> reads(map), reads(key), reads(key_env), writes(visit_env) {
  let hash = HashMapKey::hash(env: key_env, key: key);
  let capacity = map^.heads.inner.len;
  if capacity == 0_u64 {
    return Err<R, unit>(error: unit);
  }
  let bucket = hash % capacity;
  let index = map^.heads.inner[bucket];
  let count = map^.entries.inner.len;
  for (step in 0_u64..count) {
    if index < count {
      let node = &map^.entries.inner[index];
      let equal = HashMapKey::equal(env: key_env, left: &node^.key, right: key);
      if equal {
        let observed = observe(env: visit_env, key: &node^.key, value: &node^.value);
        return Ok<R, unit>(value: move observed);
      }
      set index = node^.next;
    } else {
      return Err<R, unit>(error: unit);
    }
  }
  return Err<R, unit>(error: unit);
}

struct ChainLookupOwner<T: drop> {
  map: ChainMap<u64, T>;
  env: MapCostEnv;
  seed: u64;
}

fn chain_lookup_prepare<interface MapCostElement<T>>(capacity: u64, count: u64, seed: u64) -> result: ChainLookupOwner<T> pure contract {
  requires capacity <= 8192_u64;
  requires count <= capacity;
} {
  let heads = chain_heads_new(capacity: capacity);
  let entries = box_slots_new::<ChainEntry<u64, T>>(capacity: capacity);
  let map = ChainMap<u64, T>(heads: move heads, entries: move entries);
  let salt = ixor(seed, 11400714819323198485_u64);
  let collide = 0_u64 != 0_u64;
  let env = MapCostEnv(salt: salt, collide: collide);
  for (index in 0_u64..count) {
    let key = map_cost_key(index: index);
    let next = seed +wrap index;
    let value = MapCostElement::make(seed: next);
    let outcome = chain_insert::<MapCostLibraryKey, T>(map: &map, key: key, value: move value, env: &env);
    match move outcome {
      Ok(value: inserted) => {
      }
      Err(error: offered) => {
        let HashMapPair(key: saved_key, value: saved_value) = move offered;
        let rejected_content = MapCostElement::content(key: saved_key, value: move saved_value);
      }
    }
  }
  return ChainLookupOwner<T>(map: move map, env: env, seed: seed);
}

fn chain_lookup_query<interface MapCostElement<T>>(owner: &ChainLookupOwner<T>, rounds: u64, miss: u64) -> result: u64 reads(owner) {
  let digest = MapCostDigest(ordered: owner^.seed, sum: 0_u64, parity: 0_u64, count: 0_u64);
  let first_key = if miss != 0_u64 {
    give 2_u64;
  } else {
    give 1_u64;
  }
  for (round in 0_u64..rounds) {
    for (index in 0_u64..owner^.map.entries.inner.len) {
      let doubled = index *wrap 2_u64;
      let key = doubled +wrap first_key;
      let found = chain_lookup::<MapCostLibraryKey, T, MapCostDigest, u64, fn MapCostElement::observe>(map: &owner^.map, key: &key, key_env: &owner^.env, visit_env: &digest);
      map_cost_lookup_result(found: found, digest: &digest);
    }
  }
  return map_cost_finish(digest: digest);
}

fn chain_lookup_finish<interface MapCostElement<T>>(owner: ChainLookupOwner<T>) -> result: u64 pure {
  let ChainLookupOwner(map: map, env: env, seed: seed) = move owner;
  let ChainMap(heads: heads, entries: entries) = move map;
  let digest = MapCostDigest(ordered: seed, sum: 0_u64, parity: 0_u64, count: 0_u64);
  loop @entries {
    if entries.inner.len == 0_u64 {
      break @entries;
    }
    let node = take_back(window: &entries.inner);
    let ChainEntry(key: saved_key, value: saved_value, next: next) = move node;
    MapCostElement::consume(env: &digest, key: saved_key, value: move saved_value);
  }
  free_empty(window: move entries);
  return map_cost_finish(digest: digest);
}

fn chain_lookup_geometry<T: drop>(owner: &ChainLookupOwner<T>) -> result: u64 reads(owner) {
  let capacity = owner^.map.heads.inner.len;
  let count = owner^.map.entries.inner.len;
  let high = capacity *wrap 4294967296_u64;
  return high +wrap count;
}

fn chain_lookup_word_prepare(capacity: u64, count: u64, seed: u64) -> result: ChainLookupOwner<u64> pure contract {
  requires capacity <= 8192_u64;
  requires count <= capacity;
} {
  return chain_lookup_prepare::<MapCostWord>(capacity: capacity, count: count, seed: seed);
}

fn chain_lookup_word_query(owner: &ChainLookupOwner<u64>, rounds: u64, miss: u64) -> result: u64 reads(owner) {
  return chain_lookup_query::<MapCostWord>(owner: owner, rounds: rounds, miss: miss);
}

fn chain_lookup_word_finish(owner: ChainLookupOwner<u64>) -> result: u64 pure {
  return chain_lookup_finish::<MapCostWord>(owner: move owner);
}

fn chain_lookup_word_geometry(owner: &ChainLookupOwner<u64>) -> result: u64 reads(owner) {
  return chain_lookup_geometry::<u64>(owner: owner);
}

fn chain_lookup_record_prepare(capacity: u64, count: u64, seed: u64) -> result: ChainLookupOwner<MapCostRecord> pure contract {
  requires capacity <= 8192_u64;
  requires count <= capacity;
} {
  return chain_lookup_prepare::<MapCostWide>(capacity: capacity, count: count, seed: seed);
}

fn chain_lookup_record_query(owner: &ChainLookupOwner<MapCostRecord>, rounds: u64, miss: u64) -> result: u64 reads(owner) {
  return chain_lookup_query::<MapCostWide>(owner: owner, rounds: rounds, miss: miss);
}

fn chain_lookup_record_finish(owner: ChainLookupOwner<MapCostRecord>) -> result: u64 pure {
  return chain_lookup_finish::<MapCostWide>(owner: move owner);
}

fn chain_lookup_record_geometry(owner: &ChainLookupOwner<MapCostRecord>) -> result: u64 reads(owner) {
  return chain_lookup_geometry::<MapCostRecord>(owner: owner);
}

