fn chain_topology_hash(env: &HashMapHashEnv, key: &u64) -> result: u64 reads(key) {
  return key^ % 2_u64;
}

binding ChainTopologyKey : HashMapKey<u64, HashMapHashEnv> {
  hash = chain_topology_hash;
  equal = hash_map_test_scalar_equal;
}

fn full_chain_topology_test() -> result: u64 pure {
  let ordinary = False();
  let env = HashMapHashEnv(hostile: ordinary);
  let seen = HashMapTestSeen(failures: 0_u64, consumed: 0_u64, key_sum: 0_u64, value_sum: 0_u64, visits: 0_u64, observed: 0_u64);
  for (selected in 0_u64..6_u64) {
    let map = full_chain_new::<u64, u64, 8>(capacity: 8_u64);
    for (key in 0_u64..6_u64) {
      let value = key *wrap 10_u64;
      let outcome = full_chain_try_put::<ChainTopologyKey, u64, 8>(map: &map, key: key, value: value, env: &env);
      hash_map_test_scalar_outcome(outcome: outcome, expected: 0_u64, key: key, value: value, seen: &seen);
    }
    let removed = full_chain_remove::<ChainTopologyKey, u64, 8>(map: &map, key: &selected, env: &env);
    match removed {
      Some(value: pair) => {
        if pair.key != selected {
          hash_map_test_fail(seen: &seen);
        }
        let expected = selected *wrap 10_u64;
        if pair.value != expected {
          hash_map_test_fail(seen: &seen);
        }
        hash_map_pair_consume::<HashMapScalarConsume>(pair: pair, env: &seen);
      }
      None() => {
        hash_map_test_fail(seen: &seen);
      }
    }
    for (key in 0_u64..6_u64) {
      let found = full_chain_lookup::<ChainTopologyKey, u64, HashMapTestSeen, u64, fn hash_map_test_scalar_read, 8>(map: &map, key: &key, key_env: &env, visit_env: &seen);
      match found {
        Ok(value: actual) => {
          if key == selected {
            hash_map_test_fail(seen: &seen);
          }
          let expected = key *wrap 10_u64;
          if actual != expected {
            hash_map_test_fail(seen: &seen);
          }
        }
        Err(error: missing) => {
          if key != selected {
            hash_map_test_fail(seen: &seen);
          }
        }
      }
    }
    full_chain_free::<HashMapScalarConsume, 8>(map: move map, env: &seen);
  }
  if seen.consumed != 36_u64 {
    hash_map_test_fail(seen: &seen);
  }
  if seen.key_sum != 90_u64 {
    hash_map_test_fail(seen: &seen);
  }
  if seen.value_sum != 900_u64 {
    hash_map_test_fail(seen: &seen);
  }
  return seen.failures;
}

fn chain_changed_hash(env: &HashMapHashEnv, key: &HashMapOwnedNode) -> result: u64 reads(env), reads(key) {
  if env^.hostile {
    if key^.child.inner.id == 3_u64 {
      return 1_u64;
    }
  }
  return 0_u64;
}

fn chain_changed_equal(env: &HashMapHashEnv, left: &HashMapOwnedNode, right: &HashMapOwnedNode) -> result: Bool reads(left), reads(right) {
  return left^.child.inner.id == right^.child.inner.id;
}

binding ChainChangedKey : HashMapKey<HashMapOwnedNode, HashMapHashEnv> {
  hash = chain_changed_hash;
  equal = chain_changed_equal;
}

fn chain_changed_visit(env: &HashMapOwnerLedger, key: &HashMapOwnedNode, value: &HashMapOwnedNode) -> result: unit reads(key), reads(value), writes(env) {
  let identifier = key^.child.inner.id;
  if identifier < 2_u64 {
    hash_map_test_owned_fail(ledger: env);
  }
  if identifier > 3_u64 {
    hash_map_test_owned_fail(ledger: env);
  }
  let expected = identifier +wrap 10_u64;
  if value^.child.inner.id != expected {
    hash_map_test_owned_fail(ledger: env);
  }
  set env^.visits = env^.visits +wrap 1_u64;
  return unit;
}

fn full_chain_changed_hash_test() -> result: u64 pure {
  let releases = array_filled::<u64, 32>(value: 0_u64);
  let ledger = HashMapOwnerLedger(releases: releases, failures: 0_u64, visits: 0_u64);
  let ordinary = False();
  let env = HashMapHashEnv(hostile: ordinary);
  let map = full_chain_new::<HashMapOwnedNode, HashMapOwnedNode, 4>(capacity: 4_u64);
  for (identifier in 1_u64..4_u64) {
    let serial = identifier +wrap 10_u64;
    let key = hash_map_test_owned_make(id: identifier, serial: identifier);
    let value = hash_map_test_owned_make(id: serial, serial: serial);
    let outcome = full_chain_try_put::<ChainChangedKey, HashMapOwnedNode, 4>(map: &map, key: move key, value: move value, env: &env);
    hash_map_test_owned_outcome(outcome: move outcome, expected: 0_u64, key: identifier, value: serial, ledger: &ledger);
  }
  set env.hostile = True();
  let key = hash_map_test_owned_make(id: 1_u64, serial: 21_u64);
  let removed = full_chain_remove::<ChainChangedKey, HashMapOwnedNode, 4>(map: &map, key: &key, env: &env);
  hash_map_test_owned_release(value: move key, ledger: &ledger);
  match move removed {
    Some(value: pair) => {
      hash_map_test_owned_check_pair(pair: &pair, key: 1_u64, value: 11_u64, ledger: &ledger);
      hash_map_pair_consume::<HashMapOwnedConsume>(pair: move pair, env: &ledger);
    }
    None() => {
      hash_map_test_owned_fail(ledger: &ledger);
    }
  }
  let stale_query = hash_map_test_owned_make(id: 2_u64, serial: 22_u64);
  let inaccessible = full_chain_lookup::<ChainChangedKey, HashMapOwnedNode, HashMapOwnerLedger, u64, fn hash_map_test_owned_read, 4>(map: &map, key: &stale_query, key_env: &env, visit_env: &ledger);
  match inaccessible {
    Ok(value: unexpected) => {
      hash_map_test_owned_fail(ledger: &ledger);
    }
    Err(error: missing) => {
    }
  }
  hash_map_test_owned_release(value: move stale_query, ledger: &ledger);
  let count = full_chain_len::<HashMapOwnedNode, HashMapOwnedNode, 4>(map: &map);
  if count != 2_u64 {
    hash_map_test_owned_fail(ledger: &ledger);
  }
  full_chain_each::<HashMapOwnedNode, HashMapOwnedNode, HashMapOwnerLedger, fn chain_changed_visit, 4>(map: &map, env: &ledger);
  full_chain_free::<HashMapOwnedConsume, 4>(map: move map, env: &ledger);
  if ledger.visits != 2_u64 {
    hash_map_test_owned_fail(ledger: &ledger);
  }
  for (serial in 0_u64..32_u64) {
    let expected = 0_u64;
    if serial >= 1_u64 {
      if serial <= 3_u64 {
        set expected = 1_u64;
      }
    }
    if serial >= 11_u64 {
      if serial <= 13_u64 {
        set expected = 1_u64;
      }
    }
    if serial == 21_u64 {
      set expected = 1_u64;
    }
    if serial == 22_u64 {
      set expected = 1_u64;
    }
    if ledger.releases[serial] != expected {
      hash_map_test_owned_fail(ledger: &ledger);
    }
  }
  return ledger.failures;
}

