#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
extern uint64_t wf_hash_map_test_scalars(void);
extern uint64_t wf_hash_map_test_wrapping(void);
extern uint64_t wf_hash_map_test_cycle(void);
extern uint64_t wf_hash_map_test_growth(void);
extern uint64_t wf_hash_map_test_edit(void);
extern uint64_t wf_hash_map_test_owned(void);
extern uint64_t wf_hash_map_test_units(void);
extern uint64_t wf_full_chain_topology_test(void);
extern uint64_t wf_full_chain_changed_hash_test(void);
extern uint64_t wf_full_chain_policy_stage(uint64_t stage);
int main(void) {
  struct test { const char *name; uint64_t (*run)(void); } tests[] = {
    {"scalars", wf_hash_map_test_scalars},
    {"wrapping", wf_hash_map_test_wrapping},
    {"cycle", wf_hash_map_test_cycle},
    {"edit", wf_hash_map_test_edit},
    {"owned", wf_hash_map_test_owned},
    {"units", wf_hash_map_test_units},
    {"topology", wf_full_chain_topology_test},
    {"changed_hash_owning_cleanup", wf_full_chain_changed_hash_test},
  };
  int failed = 0;
  for (size_t i = 0; i < sizeof(tests)/sizeof(tests[0]); ++i) {
    uint64_t count = tests[i].run();
    printf("%s failures=%" PRIu64 "\n", tests[i].name, count);
    if (count != 0) failed = 1;
  }
  uint64_t policy = wf_hash_map_test_growth();
  printf("current_flat_growth_policy failures=%" PRIu64 " (known prototype contract difference)\n", policy);
  if (policy != 8) { puts("unexpected number of policy differences"); failed = 1; }
  const uint64_t expected[][3] = {{8,6,0},{16,7,0},{16,11,0},{16,1,10},{16,2,10},{16,3,0},{16,2,1},{16,3,0},{3,3,0},{6,4,0},{16,6,6},{32,7,0},{16,5,7},{16,6,0},{64,8,40},{64,9,40}};
  for (uint64_t stage = 0; stage < 16; ++stage) {
    uint64_t packed = wf_full_chain_policy_stage(stage);
    uint64_t capacity = packed & 255, length = packed >> 8;
    uint64_t expected_actual_capacity = stage == 11 ? 16 : expected[stage][0];
    printf("policy_stage=%" PRIu64 " expected=%" PRIu64 ",%" PRIu64 ",%" PRIu64 " actual=%" PRIu64 ",%" PRIu64 ",0\n", stage, expected[stage][0], expected[stage][1], expected[stage][2], capacity, length);
    if (capacity != expected_actual_capacity || length != expected[stage][1]) failed = 1;
  }
  return failed;
}

sources.full-chain-operations.wf:
struct FullChainEntry<K, V> {
  key: K;
  value: V;
  next: u64;
}

struct FullChainMap<K, V, const ceiling: u64> {
  heads: Box<Slots<u64>>;
  entries: Box<Slots<FullChainEntry<K, V>>>;
}

fn full_chain_heads<const ceiling: u64>(capacity: u64) -> result: Box<Slots<u64>> pure contract {
  requires capacity <= ceiling;
  requires ceiling <= 8192_u64;
  ensures result.inner.len == capacity;
} {
  let heads = box_slots_new::<u64>(capacity: capacity);
  for @heads (
    index in 0_u64..capacity,
    invariant minimum: heads.inner.len >= index,
    invariant maximum: heads.inner.len <= index,
    invariant capacity: heads.inner.cap >= capacity
  ) {
    place_back(window: &heads.inner, value: 18446744073709551615_u64);
  }
  invariant complete_min: heads.inner.len >= capacity;
  invariant complete_max: heads.inner.len <= capacity;
  return move heads;
}

fn full_chain_new<K, V, const ceiling: u64>(capacity: u64) -> result: FullChainMap<K, V, ceiling> pure contract {
  requires capacity <= ceiling;
  requires ceiling <= 8192_u64;
} {
  let heads = full_chain_heads::<ceiling>(capacity: capacity);
  let entries = box_slots_new::<FullChainEntry<K, V>>(capacity: capacity);
  return FullChainMap<K, V, ceiling>(heads: move heads, entries: move entries);
}

fn full_chain_len<K, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>) -> result: u64 reads(map) {
  return map^.entries.inner.len;
}

fn full_chain_capacity<K, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>) -> result: u64 reads(map) {
  return map^.heads.inner.len;
}

fn full_chain_find<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, env: &E) -> result: Result<u64, unit> reads(map), reads(key), reads(env) contract {
  ensures when Ok(value: index): index < map^.entries.inner.len;
} {
  let hash = HashMapKey::hash(env: env, key: key);
  let capacity = map^.heads.inner.len;
  if capacity == 0_u64 {
    return Err<u64, unit>(error: unit);
  }
  let bucket = hash % capacity;
  let index = map^.heads.inner[bucket];
  let count = map^.entries.inner.len;
  for (step in 0_u64..count) {
    if index < count {
      let node = &map^.entries.inner[index];
      let equal = HashMapKey::equal(env: env, left: &node^.key, right: key);
      if equal {
        return Ok<u64, unit>(value: index);
      }
      set index = node^.next;
    } else {
      return Err<u64, unit>(error: unit);
    }
  }
  return Err<u64, unit>(error: unit);
}

fn full_chain_lookup<interface HashMapKey<K, E>, V, F, R, fn observe(env: &F, key: &K, value: &V) -> result: R reads(key), reads(value), writes(env), const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, key_env: &E, visit_env: &F) -> result: Result<R, unit> reads(map), reads(key), reads(key_env), writes(visit_env) {
  let found = full_chain_find::<HashMapKey<K, E>, V, ceiling>(map: map, key: key, env: key_env);
  match found {
    Ok(value: index) => {
      let node = &map^.entries.inner[index];
      let observed = observe(env: visit_env, key: &node^.key, value: &node^.value);
      return Ok<R, unit>(value: move observed);
    }
    Err(error: missing) => {
      return Err<R, unit>(error: unit);
    }
  }
}

fn full_chain_edit<interface HashMapKey<K, E>, V, F, R, fn update(env: &F, key: &K, value: &V) -> result: R reads(key), writes(env), writes(value), const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, key_env: &E, edit_env: &F) -> result: Result<R, unit> reads(key), reads(key_env), writes(map), writes(edit_env) contract {
  ensures map^.heads.inner.len == entry(map)^.heads.inner.len;
  ensures map^.entries.inner.len == entry(map)^.entries.inner.len;
  ensures map^.entries.inner.cap == entry(map)^.entries.inner.cap;
} {
  let found = full_chain_find::<HashMapKey<K, E>, V, ceiling>(map: map, key: key, env: key_env);
  match found {
    Ok(value: index) => {
      let node = &map^.entries.inner[index];
      let updated = update(env: edit_env, key: &node^.key, value: &node^.value);
      return Ok<R, unit>(value: move updated);
    }
    Err(error: missing) => {
      return Err<R, unit>(error: unit);
    }
  }
}

fn full_chain_try_put<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: K, value: V, env: &E) -> result: HashMapPut<K, V> reads(env), writes(map) contract {
  ensures map^.heads.inner.len == entry(map)^.heads.inner.len;
  ensures map^.entries.inner.cap == entry(map)^.entries.inner.cap;
} {
  let hash = HashMapKey::hash(env: env, key: &key);
  let capacity = map^.heads.inner.len;
  if capacity > 0_u64 {
    let bucket = hash % capacity;
    let first = map^.heads.inner[bucket];
    let index = first;
    let count = map^.entries.inner.len;
    for @find (step in 0_u64..count) {
      if index < count {
        let node = &map^.entries.inner[index];
        let equal = HashMapKey::equal(env: env, left: &node^.key, right: &key);
        if equal {
          swap(first: &node^.key, second: &key);
          swap(first: &node^.value, second: &value);
          let previous = HashMapPair<K, V>(key: move key, value: move value);
          let reason = HashMapReturnReason::HashMapReplaced();
          return HashMapPut<K, V>::HashMapReturned(reason: reason, pair: move previous);
        }
        set index = node^.next;
      } else {
        break @find;
      }
    }
    if count < capacity {
      if count < ceiling {
        if count < map^.entries.inner.cap {
          let node = FullChainEntry<K, V>(key: move key, value: move value, next: first);
          place_back(window: &map^.entries.inner, value: move node);
          set map^.heads.inner[bucket] = count;
          return HashMapPut<K, V>::HashMapInserted();
        }
      }
    }
  }
  let offered = HashMapPair<K, V>(key: move key, value: move value);
  let reason = HashMapReturnReason::HashMapFull();
  return HashMapPut<K, V>::HashMapReturned(reason: reason, pair: move offered);
}

fn full_chain_relink<K, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, old: u64, replacement: u64) -> result: unit writes(map) contract {
  ensures map^.heads.inner.len == entry(map)^.heads.inner.len;
  ensures map^.entries.inner.len == entry(map)^.entries.inner.len;
  ensures map^.entries.inner.cap == entry(map)^.entries.inner.cap;
} {
  let buckets = map^.heads.inner.len;
  for (index in 0_u64..buckets) {
    if map^.heads.inner[index] == old {
      set map^.heads.inner[index] = replacement;
    }
  }
  let count = map^.entries.inner.len;
  for (index in 0_u64..count) {
    if map^.entries.inner[index].next == old {
      set map^.entries.inner[index].next = replacement;
    }
  }
  return unit;
}

fn full_chain_remove<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, env: &E) -> result: Option<HashMapPair<K, V>> reads(key), reads(env), writes(map) {
  let count = map^.entries.inner.len;
  if count == 0_u64 {
    return None<HashMapPair<K, V>>();
  }
  let hash = HashMapKey::hash(env: env, key: key);
  let buckets = map^.heads.inner.len;
  if buckets == 0_u64 {
    return None<HashMapPair<K, V>>();
  }
  let bucket = hash % buckets;
  let index = map^.heads.inner[bucket];
  let predecessor = count;
  for (step in 0_u64..count) {
    if index < count {
      let equal = HashMapKey::equal(env: env, left: &map^.entries.inner[index].key, right: key);
      if equal {
        let next = map^.entries.inner[index].next;
        if predecessor < count {
          set map^.entries.inner[predecessor].next = next;
        } else {
          set map^.heads.inner[bucket] = next;
        }
        let removed = take_back(window: &map^.entries.inner);
        let last = map^.entries.inner.len;
        if index < last {
          swap(first: &map^.entries.inner[index], second: &removed);
          let moved_hash = HashMapKey::hash(env: env, key: &map^.entries.inner[index].key);
          let moved_bucket = moved_hash % buckets;
          let cursor = map^.heads.inner[moved_bucket];
          if cursor == last {
            set map^.heads.inner[moved_bucket] = index;
          } else {
            for @repair (attempt in 0_u64..last) {
              if cursor < last {
                let link = map^.entries.inner[cursor].next;
                if link == last {
                  set map^.entries.inner[cursor].next = index;
                  break @repair;
                }
                set cursor = link;
              } else {
                break @repair;
              }
            }
          }
        }
        let FullChainEntry(key: saved_key, value: saved_value, next: discarded_next) = move removed;
        let pair = HashMapPair<K, V>(key: move saved_key, value: move saved_value);
        return Some<HashMapPair<K, V>>(value: move pair);
      }
      set predecessor = index;
      set index = map^.entries.inner[index].next;
    } else {
      return None<HashMapPair<K, V>>();
    }
  }
  return None<HashMapPair<K, V>>();
}

fn full_chain_rebuild<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, capacity: u64, env: &E) -> result: Result<unit, unit> reads(env), writes(map) contract {
  requires ceiling <= 8192_u64;
} {
  if capacity > ceiling {
    return Err<unit, unit>(error: unit);
  }
  if capacity < map^.heads.inner.len {
    return Err<unit, unit>(error: unit);
  }
  if capacity < map^.entries.inner.len {
    return Err<unit, unit>(error: unit);
  }
  if capacity == 0_u64 {
    return Ok<unit, unit>(value: unit);
  }
  let heads = full_chain_heads::<ceiling>(capacity: capacity);
  if map^.entries.inner.cap < capacity {
    grow(cell: &map^.entries, capacity: capacity);
  }
  let count = map^.entries.inner.len;
  for (step in 0_u64..count) {
    let reverse = count - step;
    let index = reverse - 1_u64;
    let hash = HashMapKey::hash(env: env, key: &map^.entries.inner[index].key);
    let bucket = hash % capacity;
    let previous = heads.inner[bucket];
    set map^.entries.inner[index].next = previous;
    set heads.inner[bucket] = index;
  }
  swap(first: &map^.heads, second: &heads);
  return Ok<unit, unit>(value: unit);
}

fn full_chain_reserve<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, capacity: u64, env: &E) -> result: Result<unit, unit> reads(env), writes(map) contract {
  requires ceiling <= 8192_u64;
} {
  if capacity > ceiling {
    return Err<unit, unit>(error: unit);
  }
  if capacity <= map^.heads.inner.len {
    return Ok<unit, unit>(value: unit);
  }
  return full_chain_rebuild::<HashMapKey<K, E>, V, ceiling>(map: map, capacity: capacity, env: env);
}

fn full_chain_rehash<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, env: &E) -> result: Result<unit, unit> reads(env), writes(map) contract {
  requires ceiling <= 8192_u64;
} {
  let capacity = map^.heads.inner.len;
  return full_chain_rebuild::<HashMapKey<K, E>, V, ceiling>(map: map, capacity: capacity, env: env);
}

fn full_chain_put<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: K, value: V, env: &E) -> result: HashMapPut<K, V> reads(env), writes(map) contract {
  requires ceiling <= 8192_u64;
} {
  let buckets = map^.heads.inner.len;
  let live = map^.entries.inner.len;
  let quarter = buckets / 4_u64;
  let limit = buckets - quarter;
  let crowded = live >= limit;
  let below_ceiling = buckets < ceiling;
  if band(crowded, below_ceiling) {
    let target = ceiling;
    if buckets == 0_u64 {
      set target = 1_u64;
    } else if buckets <= 9223372036854775807_u64 {
      let widened = buckets + buckets;
      if widened <= ceiling {
        set target = widened;
      }
    }
    let grown = full_chain_rebuild::<HashMapKey<K, E>, V, ceiling>(map: map, capacity: target, env: env);
  }
  return full_chain_try_put::<HashMapKey<K, E>, V, ceiling>(map: map, key: move key, value: move value, env: env);
}

fn full_chain_each<K, V, E, fn visit(env: &E, key: &K, value: &V) -> result: unit reads(key), reads(value), writes(env), const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, env: &E) -> result: unit reads(map), writes(env) {
  let count = map^.entries.inner.len;
  for (index in 0_u64..count) {
    let node = &map^.entries.inner[index];
    visit(env: env, key: &node^.key, value: &node^.value);
  }
  return unit;
}

fn full_chain_free<interface HashMapConsume<K, V, E>, const ceiling: u64>(map: FullChainMap<K, V, ceiling>, env: &E) -> result: unit writes(env) {
  let FullChainMap(heads: heads, entries: entries) = move map;
  loop @cleanup {
    if entries.inner.len == 0_u64 {
      break @cleanup;
    }
    let node = take_back(window: &entries.inner);
    let FullChainEntry(key: saved_key, value: saved_value, next: discarded_next) = move node;
    HashMapConsume::consume(env: env, key: move saved_key, value: move saved_value);
  }
  free_empty(window: move entries);
  return unit;
}

