fn full_chain_policy_stage(stage: u64) -> result: u64 pure {
  doc "The growth policy, observed through capacity, length and the vacated count: a map of eight buckets holds six pairs and doubles before the seventh; once removals leave 10 of its 16 buckets vacated and one filled, it rebuilds at the same capacity when an insertion would find three quarters already used, clearing the vacated count; an insertion that reuses a vacated bucket uncounts it; a map of three buckets fills all three before it grows; at the mark of twelve of sixteen buckets, a map with half that mark filled doubles while one with one fewer is rebuilt at the same capacity; and a map at its ceiling of 64 buckets, with 8 filled and 40 vacated, is not rebuilt by an insertion that reaches the mark.";
  let seen = HashMapTestSeen(failures: 0_u64, consumed: 0_u64, key_sum: 0_u64, value_sum: 0_u64, visits: 0_u64, observed: 0_u64);
  let false_value = False();
  let env = HashMapHashEnv(hostile: false_value);
  let map = full_chain_new::<u64, u64, 64>(capacity: 8_u64);
  for (key in 0_u64..6_u64) {
    hash_map_test_growth_put(map: &map, key: key, env: &env, seen: &seen);
  }
  if stage == 0_u64 {
    let actual_capacity = full_chain_capacity::<u64, u64, 64>(map: &map);
    let actual_length = full_chain_len::<u64, u64, 64>(map: &map);
    let high = actual_length *wrap 256_u64;
    let packed = high +wrap actual_capacity;
    full_chain_free::<HashMapScalarConsume, 64>(map: move map, env: &seen);
    return packed;
  }
  hash_map_test_growth_shape(map: &map, capacity: 8_u64, length: 6_u64, vacated: 0_u64, seen: &seen);
  hash_map_test_growth_put(map: &map, key: 6_u64, env: &env, seen: &seen);
  if stage == 1_u64 {
    let actual_capacity = full_chain_capacity::<u64, u64, 64>(map: &map);
    let actual_length = full_chain_len::<u64, u64, 64>(map: &map);
