+}
+
+fn probe_groups_new<K, V>(count: u64) -> result: Box<Slots<ProbeGroup<K, V>>> pure contract {
+  requires count <= 1024_u64;
+} {
+  let groups = box_slots_new::<ProbeGroup<K, V>>(capacity: count);
+  for @fill (
+    index in 0_u64..count,
+    invariant filled_min: groups.inner.len >= index,
+    invariant filled_max: groups.inner.len <= index,
+    invariant capacity: groups.inner.cap >= count
+  ) {
