+} {
+  return probe_groups_new::<u64, MapCostRecord>(count: count);
+}
+
+fn probe_group_available<K, V>(slot: &GroupSlot<K, V>) -> result: Bool reads(slot) {
+  match slot^ {
+    HashMapVacant() => {
+      return 0_u64 == 0_u64;
+    }
+    HashMapDeleted() => {
+      return 0_u64 == 0_u64;
+    }
+    HashMapFilled(key: saved_key, value: saved_value) => {
+      return 0_u64 != 0_u64;
+    }
+  }
+}
+
+fn probe_group_insert<interface HashMapKey<K, E>, V>(groups: &Box<Slots<ProbeGroup<K, V>>>, key: K, value: V, env: &E) -> result: GroupSlot<K, V> reads(env), writes(groups) {
+  let hash = HashMapKey::hash(env: env, key: &key);
+  let offered = GroupSlot<K, V>::HashMapFilled(key: move key, value: move value);
+  let count = groups^.inner.len;
+  if count == 0_u64 {
+    return move offered;
+  }
+  let home = hash / 8_u64;
+  let group_index = home % count;
+  let fingerprint = ishr(hash, 57_u32);
+  for @groups (
+    step in 0_u64..count,
+    invariant group_bound: group_index < count
+  ) {
+    for (lane in 0_u64..8_u64) {
+      let vacant = probe_group_available::<K, V>(slot: &groups^.inner[group_index].slots[lane]);
+      if vacant {
+        swap(first: &groups^.inner[group_index].slots[lane], second: &offered);
+        let distance = lane * 8_u64;
+        let shift = cvt::<u64, u32>(distance);
+        let byte_mask = ishl(255_u64, shift);
+        let inverse_mask = inot(byte_mask);
+        let old_control = groups^.inner[group_index].controls;
+        let kept = iand(old_control, inverse_mask);
+        let bits = ishl(fingerprint, shift);
+        set groups^.inner[group_index].controls = ior(kept, bits);
+        return move offered;
+      }
+    }
+    let next = group_index + 1_u64;
+    if next < count {
+      set group_index = next;
+    } else {
+      set group_index = 0_u64;
+    }
+  }
+  return move offered;
+}
+
+struct GroupLookupOwner<T: drop> {
+  groups: Box<Slots<ProbeGroup<u64, T>>>;
+  env: MapCostEnv;
+  seed: u64;
+  count: u64;
+}
+
+fn group_lookup_prepare<interface MapCostElement<T>>(capacity: u64, count: u64, seed: u64) -> result: GroupLookupOwner<T> pure contract {
+  requires capacity <= 8192_u64;
+  requires count <= capacity;
