+    let next = seed +wrap index;
+    let value = MapCostElement::make(seed: next);
+    let previous = probe_group_insert::<MapCostLibraryKey, T>(groups: &groups, key: key, value: move value, env: &env);
+    match move previous {
+      HashMapVacant() => {
+        set inserted = inserted +wrap 1_u64;
+      }
+      HashMapDeleted() => {
+        set inserted = inserted +wrap 1_u64;
+      }
+      HashMapFilled(key: old_key, value: old_value) => {
+        let rejected_content = MapCostElement::content(key: old_key, value: move old_value);
+      }
+    }
+  }
+  return GroupLookupOwner<T>(groups: move groups, env: env, seed: seed, count: inserted);
+}
+
+fn group_lookup_query<interface MapCostElement<T>>(owner: &GroupLookupOwner<T>, rounds: u64, miss: u64) -> result: u64 reads(owner) {
+  let digest = MapCostDigest(ordered: owner^.seed, sum: 0_u64, parity: 0_u64, count: 0_u64);
