+      map_cost_lookup_result(found: found, digest: &digest);
+    }
+  }
+  return map_cost_finish(digest: digest);
+}
+
+fn group_lookup_finish<interface MapCostElement<T>>(owner: GroupLookupOwner<T>) -> result: u64 pure {
+  let GroupLookupOwner(groups: groups, env: env, seed: seed, count: count) = move owner;
+  let digest = MapCostDigest(ordered: seed, sum: 0_u64, parity: 0_u64, count: 0_u64);
+  loop @groups {
+    if groups.inner.len == 0_u64 {
+      break @groups;
+    }
+    let group = take_back(window: &groups.inner);
+    let ProbeGroup(controls: controls, slots: slots) = move group;
+    let cells = slots_from_array::<GroupSlot<u64, T>, 8>(values: move slots);
+    loop @cells {
+      if cells.len == 0_u64 {
+        break @cells;
+      }
+      let slot = take_back(window: &cells);
+      match move slot {
+        HashMapVacant() => {
+        }
+        HashMapDeleted() => {
+        }
+        HashMapFilled(key: saved_key, value: saved_value) => {
+          MapCostElement::consume(env: &digest, key: saved_key, value: move saved_value);
+        }
+      }
+    }
+  }
+  free_empty(window: move groups);
+  return map_cost_finish(digest: digest);
+}
+
+fn group_lookup_geometry<T: drop>(owner: &GroupLookupOwner<T>) -> result: u64 reads(owner) {
+  let capacity = owner^.groups.inner.len *wrap 8_u64;
+  let high = capacity *wrap 4294967296_u64;
+  return high +wrap owner^.count;
+}
+
+fn group_lookup_word_prepare(capacity: u64, count: u64, seed: u64) -> result: GroupLookupOwner<u64> pure contract {
+  requires capacity <= 8192_u64;
+  requires count <= capacity;
+} {
