+}
+
+fn group_lookup_word_query(owner: &GroupLookupOwner<u64>, rounds: u64, miss: u64) -> result: u64 reads(owner) {
+  return group_lookup_query::<MapCostWord>(owner: owner, rounds: rounds, miss: miss);
+}
+
+fn group_lookup_word_finish(owner: GroupLookupOwner<u64>) -> result: u64 pure {
+  return group_lookup_finish::<MapCostWord>(owner: move owner);
+}
+
+fn group_lookup_word_geometry(owner: &GroupLookupOwner<u64>) -> result: u64 reads(owner) {
